import { Readable } from 'node:stream';
async function main(): Promise<void> {
  const r: any = new Readable({ read() {} });
  // `any` through a Json-typed call result: a thenable the await has to suspend on
  const holder: any = { p: r.toArray() };
  setTimeout(() => { r.push('z'); r.push(null); }, 20);
  const out: any = await holder.p;
  console.log(out.length, String(out[0]));
  const plain: any = { v: 3 };
  console.log((await plain).v);
}
